mapper.select:
SELECT
    bdir.*,
    bip.run_flag
FROM
    bpm_data_inst_rel bdir
LEFT JOIN bpm_inst_process bip ON bdir.inst_process_id = bip.id

    bdir.data_id = #{dataId}
    AND bip.run_flag = #{runFlag}

        AND bdir.temp_process_id = #{tempProcessId}

SELECT CONCAT('bpm','_',dir.module_schema) AS name, COUNT( dir.data_id ) AS value FROM bpm_inst_process p LEFT JOIN bpm_inst_node_audit ina ON p.id = ina.inst_process_id LEFT JOIN bpm_data_inst_rel dir ON p.id = dir.inst_process_id WHERE dir.module_schema IS NOT NULL AND dir.del_flag <> 2 AND (p.run_flag = #{pageDTO.processRunFlag} OR p.pass_flag = #{pageDTO.processRunFlag}) AND ina.audit_data_id IN
#{auditDataId}
GROUP BY dir.module_schema ORDER BY MAX(p.create_time) ASC

SELECT dir.data_id FROM bpm_inst_process p LEFT JOIN bpm_inst_node_audit ina ON p.id = ina.inst_process_id LEFT JOIN bpm_data_inst_rel dir ON p.id = dir.inst_process_id WHERE dir.module_schema = #{pageDTO.moduleSchema} AND (p.run_flag = #{pageDTO.processRunFlag} OR p.pass_flag = #{pageDTO.processRunFlag}) AND ina.audit_data_id IN
#{auditDataId}
GROUP BY dir.data_id ORDER BY MAX(p.create_time) ASC

mapper.delete:
UPDATE bpm_data_inst_rel
SET del_flag = 2
WHERE module_id = #{moduleId}
AND data_id IN

    #{id}
